mapper.select:
select * from (
    select pm.*,
           row_number() over (
               partition by least(pm.user_id, pm.receive_id), greatest(pm.user_id, pm.receive_id)
               order by pm.date_time desc, pm.id desc
           ) as rn
    from private_message pm
    where pm.user_id = #{userId} or pm.receive_id = #{userId}
) t
where t.rn = 1
and (t.user_id in
#{peerId}
or t.receive_id in
#{peerId}
)
